import java.util.*;
import java.util.stream.Collectors;

public class CollectorDemonstration {
    public record Transaction(String category, double amount, String currency) {}

    public static void main(String[] args) {
        List<Transaction> txs = List.of(
            new Transaction("Food", 15.50, "USD"),
            new Transaction("Food", 12.00, "USD"),
            new Transaction(
                "Tech", 1200.00, "USD"),
            new Transaction("Tech", 45.00, "USD")
        );

        // 1. groupingBy with downstream summing
        Map<String, Double> totalsByCategory = txs.stream()
            .collect(Collectors.groupingBy(
                Transaction::category,
                Collectors.summingDouble(Transaction::amount)
            ));

        // 2. partitioningBy into high-value vs low-value
        Map<Boolean, List<Transaction>> partitioned = txs.stream()
            .collect(Collectors.partitioningBy(tx -> tx.amount() > 100.0));

        // 3. toMap with collision resolution
        Map<String, Double> maxAmountByCategory = txs.stream()
            .collect(Collectors.toMap(
                Transaction::category,
                Transaction::amount,
                Double::max
            ));

        // 4. collectingAndThen for unmodifiable result
        List<String> expensiveCategories = txs.stream()
            .filter(tx -> tx.amount() > 50.0)
            .map(Transaction::category)
            .collect(Collectors.collectingAndThen(
                Collectors.toSet(),
                Set::copyOf
            ));

        System.out.println("Totals: " + totalsByCategory);
        System.out.println("Expensive Categories: " + expensiveCategories);
    }
}
